function update(dt){frame++;if(toastTime>0)toastTime--;if(scene!=='play'||paused)return;elapsed+=dt;if(invuln>0)invuln-=dt;if(starPower>0)starPower-=dt;
 const acceleration=keys.run?.42:.28,maxSpeed=keys.run?2.45:1.55;if(keys.left){hero.vx-=acceleration;hero.facing=-1}if(keys.right){hero.vx+=acceleration;hero.facing=1}if(!keys.left&&!keys.right)hero.vx*=.78;hero.vx=clamp(hero.vx,-maxSpeed,maxSpeed);
 if(keys.jump&&hero.ground){hero.vy=-5.15;hero.ground=false;sound(420,.075,'square',.025)}hero.vy=Math.min(hero.vy+.25,6);let oldY=hero.y;hero.x=clamp(hero.x+hero.vx,0,levelData.length);hero.y+=hero.vy;hero.ground=false;
 for(const p of levelData.plats){if(hero.x+hero.w>p.x&&hero.x<p.x+p.w&&oldY+hero.h<=p.y+2&&hero.y+hero.h>=p.y&&hero.vy>=0){hero.y=p.y-hero.h;hero.vy=0;hero.ground=true}}
 for(const p of levelData.pipes){if(hero.x+hero.w>p.x+2&&hero.x<p.x+28&&hero.y+hero.h>p.y){if(hero.vx>0)hero.x=p.x-hero.w;else if(hero.vx<0)hero.x=p.x+28;hero.vx=0}}
 for(const item of levelData.items){if(item.got)continue;let dx=hero.x+hero.w/2-item.x,dy=hero.y+hero.h/2-item.y;if(Math.abs(dx)<15&&Math.abs(dy)<17){item.got=true;if(item.type==='coin'){coins++;score+=100;sound(860,.08,'sine')}else if(item.type==='mushroom'){hero.big=true;score+=500;sound(520,.15,'triangle');notify('SUPER MARIO!')}else{starPower=7;score+=1000;sound(980,.2,'triangle');notify('STAR POWER!')}}}
 for(const e of levelData.foes){if(!e.alive)continue;e.x+=e.vx;if(Math.abs(e.x-e.base)>38)e.vx*=-1;if(e.type==='fly')e.y=130+Math.sin(frame*.08+e.base)*19;else e.y=145;
 if(hero.x+hero.w>e.x-8&&hero.x<e.x+12&&hero.y+hero.h>e.y-12&&hero.y<e.y+9){if(hero.vy>0&&oldY+hero.h<e.y+6){e.alive=false;hero.vy=-3.7;score+=200;sound(240,.1);burst(e.x,e.y,'#ffb35a',7)}else hurt()}}
 const b=levelData.boss;if(b.active&&hero.x>levelData.length-330){b.phase+=dt*3;b.x=levelData.length-135+Math.sin(b.phase)*26;b.y=125+Math.sin(b.phase*1.7)*5;
 if(hero.x+hero.w>b.x-12&&hero.x<b.x+27&&hero.y+hero.h>b.y-15&&hero.y<b.y+15){if(hero.vy>0&&oldY+hero.h<b.y+8){b.hp--;hero.vy=-4.5;score+=1000;sound(190,.16,'sawtooth');burst(b.x,b.y,'#ff6d79',14);if(b.hp<=0){b.active=false;notify('BOSS DEFEATED!')}}else hurt()}}
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx;p.y+=p.vy;p.vy+=p.type==='shot'?0:.05;p.life--;if(p.type==='shot'){for(const e of levelData.foes){if(e.alive&&Math.abs(p.x-e.x)<10){e.alive=false;p.life=0;score+=200}}if(levelData.boss.active&&Math.abs(p.x-levelData.boss.x)<15){levelData.boss.hp--;p.life=0;score+=500;if(levelData.boss.hp<=0)levelData.boss.active=false}}if(p.life<=0)particles.splice(i,1)}
 if(hero.y>H+20)hurt(true);camera=clamp(hero.x-105,0,levelData.length-W+20);if(hero.x>levelData.length-60&&!levelData.boss.active){nextLevel()}
 if(mode===1&&elapsed>90){hurt(true);elapsed=0;notify('TIME UP!')}
 if(mode===2&&elapsed>80){nextLevel()}
 hero.anim+=Math.abs(hero.vx)*.11;if(keys.special)shoot();
}
function hurt(fall=false){if(invuln>0)return;if(hero.big&&!fall){hero.big=false;invuln=1.5;sound(150,.18,'sawtooth');notify('POWER DOWN!');return}lives--;invuln=1.3;hero.vx=0;hero.vy=-3;sound(110,.25,'sawtooth');if(lives<=0){scene='over';save()}else if(fall){hero.x=Math.max(24,camera+20);hero.y=110;hero.vy=0}}
