function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*2.8,vy:-Math.random()*2,life:18+Math.random()*18,color,type:'spark'})}
function drawCloud(x,y,s=1){rect(ctx,x+5*s,y,20*s,6*s,'#ffffffaa');rect(ctx,x,y+5*s,29*s,9*s,'#ffffffcc');rect(ctx,x+7*s,y+2*s,11*s,8*s,'#fff')}
function drawWorld(){const theme=worlds[world];rect(ctx,0,0,W,H,theme.sky);
 if(world===2){for(let i=0;i<36;i++){let x=(i*89-camera*.12)%340;if(x<0)x+=340;rect(ctx,x,(i*37)%95,1+(i%3===0),1,'#fff5b4')}}
 // distant layered hills
 for(let i=0;i<6;i++){let x=(i*88-camera*.22)%430-55;rect(ctx,x,104,75,60,theme.hills);rect(ctx,x+10,92,55,18,theme.hills);rect(ctx,x+20,85,32,12,theme.hills);rect(ctx,x+25,88,7,5,'#ffffff22')}
 if(world!==2){for(let i=0;i<4;i++){let x=(i*125-camera*.08)%400-30;drawCloud(x,26+(i%2)*18,.8)}}
 // far little trees
 for(let i=0;i<12;i++){let x=(i*72-camera*.45)%380-30;rect(ctx,x+8,124,5,21,'#81513c');rect(ctx,x,111,21,17,world===1?'#e787a0':'#299b70');rect(ctx,x+4,105,14,9,world===1?'#f7afc1':'#49bd79')}
 // ground beds
 for(const p of levelData.plats){let x=p.x-camera;if(x+p.w<0||x>W)continue;if(p.type==='ground'){rect(ctx,x,p.y,p.w,p.h,world===1?'#9c5364':world===2?'#394f9c':'#278b5a');rect(ctx,x,p.y,p.w,5,theme.ground);rect(ctx,x,p.y+5,p.w,2,'#83de75');for(let tx=Math.floor(x/16)*16;tx<x+p.w;tx+=16){rect(ctx,tx,p.y+11,8,2,'#ffffff13');rect(ctx,tx+5,p.y+24,7,2,'#0000001c')}}else{rect(ctx,x,p.y,p.w,p.h,world===1?'#ed9a76':'#d78344');rect(ctx,x,p.y,p.w,2,'#ffcf70');for(let tx=x+10;tx<x+p.w;tx+=20){rect(ctx,tx,p.y+3,1,p.h-3,'#873f40');rect(ctx,tx-8,p.y+5,9,1,'#873f40')}}}
 for(const p of levelData.pipes){let x=p.x-camera;if(x<-35||x>W)continue;rect(ctx,x+3,p.y+5,23,p.h,'#13855b');rect(ctx,x,p.y,30,9,'#20b66d');rect(ctx,x+2,p.y+2,26,3,'#6be386');rect(ctx,x+5,p.y+10,4,p.h-10,'#4bd27c');rect(ctx,x+25,p.y+10,3,p.h-10,'#075d4a')}
 // goal flag
 let fx=levelData.flag-camera;if(fx>-5&&fx<W){rect(ctx,fx,91,3,68,'#e8e8d0');rect(ctx,fx+3,94,20,13,'#ffdf67');rect(ctx,fx+3,94,8,5,'#ff7190')}
}
function drawCoin(x,y){let w=frame%12<6?8:4;rect(ctx,x-w/2,y-6,w,12,'#ffc844');rect(ctx,x-w/2+1,y-4,Math.max(1,w-2),8,'#ffec82');rect(ctx,x-1,y-3,2,6,'#fff5bd')}
function drawHero(x,y){if(invuln>0&&frame%6<3)return;let h=hero.big?24:19,y0=y+(hero.big?-5:0),walk=Math.floor(hero.anim)%2; // shadow
 rect(ctx,x+1,y0+(hero.big?23:18),12,2,'#16284b55');
 // cap and hair
 rect(ctx,x+2,y0,9,4,'#e8443e');rect(ctx,x+1,y0+3,12,3,'#cf302f');rect(ctx,x+7,y0+1,5,2,'#ff7960');
 // face
 rect(ctx,x+3,y0+5,8,5,'#ffc18d');rect(ctx,x+1,y0+6,3,5,'#f3a978');rect(ctx,x+9,y0+7,2,2,'#252440');rect(ctx,x+5,y0+9,5,2,'#764437');
 // overalls & shirt
 rect(ctx,x+2,y0+10,10,6,'#338bdb');rect(ctx,x+4,y0+10,5,6,'#56b2f3');rect(ctx,x+1,y0+10,3,4,'#f15345');rect(ctx,x+10,y0+10,3,4,'#f15345');rect(ctx,x+5,y0+11,2,2,'#ffe175');rect(ctx,x+9,y0+11,2,2,'#ffe175');
 // legs/shoes
 rect(ctx,x+3,y0+16,4,3,'#245ca5');rect(ctx,x+8,y0+16,4,3,'#245ca5');if(hero.ground&&Math.abs(hero.vx)>.3){rect(ctx,x+(walk?0:4),y0+18,5,2,'#6d3d37');rect(ctx,x+(walk?7:3),y0+17,5,3,'#6d3d37')}else{rect(ctx,x+1,y0+17,5,2,'#6d3d37');rect(ctx,x+8,y0+17,5,2,'#6d3d37')}
}
function drawEnemy(e){let x=e.x-camera,y=e.y;if(e.type==='fly'){rect(ctx,x+1,y,9,7,'#8e5bb5');rect(ctx,x-3,y-3,7,3,'#f4a8ff');rect(ctx,x+8,y-3,7,3,'#f4a8ff');rect(ctx,x+2,y+2,2,2,'#fff');rect(ctx,x+8,y+2,2,2,'#fff')}else{rect(ctx,x,y+3,12,8,'#a85b3d');rect(ctx,x+2,y,8,6,'#c87a49');rect(ctx,x+2,y+5,2,3,'#fff');rect(ctx,x+8,y+5,2,3,'#fff');rect(ctx,x+3,y+6,1,2,'#2c2143');rect(ctx,x+9,y+6,1,2,'#2c2143');rect(ctx,x+1,y+10,4,2,'#633c38');rect(ctx,x+8,y+10,4,2,'#633c38')}}

